<?php
require_once __DIR__.'/../includes/auth.php'; require_once __DIR__.'/../includes/helpers.php'; require_role(['Supervisor','HR Admin','Admin']); $pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf($_POST['csrf']??null);$id=(int)($_POST['id']??0);$status=$_POST['status']??'';if(in_array($status,['Approved','Rejected','Issued'],true)){$st=$pdo->prepare("UPDATE item_requests SET status=?,approved_by=? WHERE id=? AND status IN ('Pending','Approved')");$st->execute([$status,current_user()['id'],$id]);}redirect($_SERVER['PHP_SELF'].'?updated=1');}
$title='Approve Item Request';$rows=$pdo->query("SELECT r.*,e.employee_code,e.full_name,e.department FROM item_requests r JOIN employees e ON e.id=r.employee_id ORDER BY (r.status='Pending') DESC,r.id DESC")->fetchAll();require __DIR__.'/../includes/header.php';?>
<div class="page-head"><div><h2>Approve Item Request</h2><p>Approve, reject, or mark employee requests as issued.</p></div></div><?php if(isset($_GET['updated'])):?><div class="card"><p>Request status updated.</p></div><?php endif;?><div class="card"><h3>Item requests (<?=count($rows)?>)</h3><div class="table-wrap"><table><tr><th>Employee</th><th>Item</th><th>Qty</th><th>Reason</th><th>Status</th><th>Action</th></tr><?php if(!$rows):?><tr><td colspan="6">No item requests found.</td></tr><?php endif;?><?php foreach($rows as $r):?><tr><td><?=e($r['employee_code'].' — '.$r['full_name'])?></td><td><?=e($r['item_name'])?></td><td><?=(int)$r['quantity']?></td><td><?=e($r['reason']??'')?></td><td><?=e($r['status'])?></td><td><?php if(in_array($r['status'],['Pending','Approved'],true)):?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button name="status" value="Approved">Approve</button> <button name="status" value="Rejected">Reject</button><?php if($r['status']==='Approved'):?> <button name="status" value="Issued">Mark Issued</button><?php endif;?></form><?php else:?>—<?php endif;?></td></tr><?php endforeach;?></table></div></div><?php require __DIR__.'/../includes/footer.php';?>